import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, float, texture, hash, length, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, TorusKnotGeometry, CylinderGeometry, TorusGeometry, PlaneGeometry, DirectionalLight, RepeatWrapping } = ctx.THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#14141a';
  const bg = colors.background ?? '#0b0b10';

  const group = new Group();
  const timelines = [];
  const prims = [];
  const disposables = [];
  let loadedTex = null;
  let disposed = false;

  // ---------- BACKDROP (gradient stage, 7x6 at z=-3) ----------
  const backdropMat = new MeshBasicNodeMaterial();
  const gy = uv().y;
  backdropMat.colorNode = mix(
    mix(color(stops[0].hex), color(stops[1].hex), smoothstep(float(stops[0].at), float(stops[1].at), gy)),
    color(stops[2].hex),
    smoothstep(float(stops[1].at), float(stops[2].at), gy)
  );
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdrop.geometry, backdropMat);

  // ---------- FLOOR (cinematic floor plane) ----------
  const floorMat = new MeshStandardNodeMaterial({ roughness: 0.85, metalness: 0.2 });
  floorMat.colorNode = mix(color(bg), color(surface), smoothstep(0.0, 1.0, uv().y));
  const floor = new Mesh(new PlaneGeometry(7, 6), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, -0.86, -0.5);
  group.add(floor);
  disposables.push(floor.geometry, floorMat);

  // ---------- CONTACT SHADOW (radial gradient, radius 1.5) ----------
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color('#000000');
  const radial = length(uv().sub(vec2(0.5, 0.5))).mul(2.0); // 0 center -> 1 rim
  shadowMat.opacityNode = smoothstep(1.0, 0.55, radial).mul(0.6);
  const shadow = new Mesh(new PlaneGeometry(3.0, 3.0), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.852, 0);
  group.add(shadow);
  disposables.push(shadow.geometry, shadowMat);

  // ---------- PEDESTAL (radius 1.1, height 0.5, top at y=-0.35) ----------
  const pedestalMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.7,
    metalness: 0.35,
  });
  pedestalMat.envMapIntensity = 0.7;
  const pedestal = new Mesh(new CylinderGeometry(1.1, 1.1, 0.5, 96), pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);
  disposables.push(pedestal.geometry, pedestalMat);

  // Chamfered top edge (0.03-unit ring catching the key light)
  const chamferMat = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.45,
    metalness: 0.5,
  });
  chamferMat.envMapIntensity = 0.7;
  const chamfer = new Mesh(new TorusGeometry(1.084, 0.018, 20, 128), chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.352, 0);
  group.add(chamfer);
  disposables.push(chamfer.geometry, chamferMat);

  // ---------- TORUS KNOT (brushed-metal material study) ----------
  const knotMat = new MeshPhysicalNodeMaterial({
    color: paper,
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // rotated 90deg to tube direction
  knotMat.envMapIntensity = 0.7;
  // Imperfection pass baseline: 2% value jitter on roughness so highlights break up
  knotMat.roughnessNode = float(0.55).add(hash(uv().mul(512.0)).sub(0.5).mul(0.04)).clamp(0.05, 1.0);

  const knotGroup = new Group();
  const knot = new Mesh(new TorusKnotGeometry(0.7, 0.22, 220, 36), knotMat);
  knotGroup.add(knot);
  knotGroup.position.set(0, 0.4, 0);
  group.add(knotGroup);
  disposables.push(knot.geometry, knotMat);

  // Roughness map injection (map multiplies, center 0.9 -> base 0.55) + scratch bump 0.15
  const mapUrl = config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(mapUrl).then((tex) => {
    if (disposed) return;
    loadedTex = tex;
    tex.wrapS = RepeatWrapping;
    tex.wrapT = RepeatWrapping;
    const mapSample = texture(tex, uv().mul(vec2(6.0, 1.0))).r;
    knotMat.roughnessNode = mapSample
      .mul(float(0.55 / 0.9))
      .add(hash(uv().mul(512.0)).sub(0.5).mul(0.04))
      .clamp(0.05, 1.0);
    knotMat.bumpMap = tex; // scratch-noise imperfection pass
    knotMat.bumpScale = 0.15;
    knotMat.needsUpdate = true;
  });

  // ---------- LIGHTS (node-local rim/accent; scene supplies ambient 0.6 + key 1.2) ----------
  const rim = new DirectionalLight(accent, 0.9);
  rim.position.set(-3, 2.2, -3.5);
  rim.target.position.set(0, 0.4, 0);
  group.add(rim);
  group.add(rim.target);

  const back = new DirectionalLight(paper, 0.7);
  back.position.set(2.5, 3, -3);
  back.target.position.set(0, 0.2, 0);
  group.add(back);
  group.add(back.target);

  // ---------- TEXT (verbatim spec copy, bimodal scale) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItem = items.find((i) => i.role === 'caption');

  const headline = ctx.fontAtlas.createText(
    headlineItem ? headlineItem.text : 'Material study 03',
    { fontSize: headlineItem?.typography?.fontSize ?? 68, color: paper, align: 'center' }
  );
  headline.position.set(0, -1.2, 0.6);
  group.add(headline);

  const caption = ctx.fontAtlas.createText(
    captionItem ? captionItem.text : 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    {
      fontSize: captionItem?.typography?.fontSize ?? 18,
      color: paper,
      align: 'center',
      letterSpacingPx: 1.5,
    }
  );
  caption.position.set(0, -1.6, 0.6);
  group.add(caption);

  // ---------- CINEMATIC PRIMITIVES ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[p.name];
    if (fn) {
      const handle = fn(knotGroup, p.params ?? {});
      if (handle) prims.push(handle);
    }
  }

  // ---------- ENTRANCE MOTION (weighted rise + settle) ----------
  const tl = gsap.timeline();
  tl.from(knotGroup.position, { y: 0.75, duration: 0.7, ease: 'power3.out' }, 0);
  tl.fromTo(
    knotGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.55
  );
  tl.from(headline.position, { y: '-=0.2', duration: 0.5, ease: 'power2.out' }, 0.15);
  tl.from(caption.position, { y: '-=0.2', duration: 0.5, ease: 'power2.out' }, 0.25);
  timelines.push(tl);

  // ---------- HANDLERS / CLEANUP ----------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    disposed = true;
    for (const t of timelines) t.kill();
    for (const p of prims) p.cleanup && p.cleanup();
    for (const d of disposables) d.dispose && d.dispose();
    if (loadedTex && loadedTex.dispose) loadedTex.dispose();
    headline.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material && o.material.dispose) o.material.dispose();
    });
    caption.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material && o.material.dispose) o.material.dispose();
    });
  };

  return group;
}
